<?php
include 'header.php';
require_once '../includes/auth_services.php';
$msg='';$type='';
$keys=['mail_host','mail_port','mail_username','mail_password','mail_encryption','mail_from_address','mail_from_name','google_client_id','google_client_secret','google_redirect_uri'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') { csrf_guard();
    $secretKeys = ['mail_password', 'google_client_secret'];
    foreach ($keys as $key) {
        $value = trim((string)($_POST[$key] ?? ''));
        if (in_array($key, $secretKeys, true) && $value === '') continue; // để trống = giữ nguyên giá trị cũ, không ghi đè
        settings_set($conn, $key, $value, 'fas fa-key');
    }
    $msg='Đã lưu cấu hình đăng nhập và email.';$type='success';
}
$cfg=[];foreach($keys as $key)$cfg[$key]=auth_setting($conn,$key,'');
$defaultRedirect=auth_absolute_url('dang-nhap-google/callback');
?>
