ho htmlspecialchars($cfg['mail_username']); ?>"></div><div class="form-group"><label class="form-label">Mã hóa</label><select class="form-control" name="mail_encryption"><option value="tls" <?php echo $cfg['mail_encryption']==='tls'?'selected':''; ?>>TLS</option><option value="ssl" <?php echo $cfg['mail_encryption']==='ssl'?'selected':''; ?>>SSL</option><option value="none" <?php echo $cfg['mail_encryption']==='none'?'selected':''; ?>>Không</option></select></div></div><div class="form-group"><label class="form-label">Mật khẩu ứng dụng</label><input class="form-control" type="password" name="mail_password" value="<?php echo htmlspecialchars($cfg['mail_password']); ?>"></div><div class="form-group"><label class="form-label">Email gửi</label><input class="form-control" type="email" name="mail_from_address" value="<?php echo htmlspecialchars($cfg['mail_from_address']); ?>"></div><div class="form-group"><label class="form-label">Tên người gửi</label><input class="form-control" name="mail_from_name" value="<?php echo htmlspecialchars($cfg['mail_from_name']); ?>"></div></div></section><div class="save-row"><button class="save-btn" type="submit"><i class="fas fa-floppy-disk"></i> Lưu cấu hình</button></div></form><?php if($msg!==''):?><script>document.addEventListener('DOMContentLoaded',function(){Swal.fire({icon:'<?php echo $type; ?>',title:'Đã lưu',text:<?php echo json_encode($msg,JSON_UNESCAPED_UNICODE); ?>,confirmButtonColor:'#9a7658'})})</script><?php endif;?>
